package com.primehr.learningdevelopment.delivery.domain;

import com.primehr.rsp.domain.RspAuditedEntity;
import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.UUID;

@Entity
@Table(name="ld_consolidated_plan",uniqueConstraints={
 @UniqueConstraint(name="uk_ld_plan_series_version",columnNames={"agency_id","series_id","plan_version"}),
 @UniqueConstraint(name="uk_ld_plan_scope_period",columnNames={"agency_id","scope_type","organization_id","planning_year","plan_version"})})
public class LdConsolidatedPlan extends RspAuditedEntity {
 public enum ScopeType{OFFICE,AGENCY} public enum Status{DRAFT,SUBMITTED,APPROVED,PUBLISHED,CANCELLED}
 @Column(name="series_id",nullable=false,length=36)private String seriesId;@Column(name="plan_version",nullable=false)private int planVersion;@Column(name="supersedes_id",length=36)private String supersedesId;
 @Enumerated(EnumType.STRING)@Column(name="scope_type",nullable=false,length=20)private ScopeType scopeType;@Column(name="organization_type",nullable=false,length=30)private String organizationType;@Column(name="organization_id",nullable=false)private Long organizationId;@Column(name="organization_code",nullable=false,length=80)private String organizationCode;@Column(name="organization_name",nullable=false,length=200)private String organizationName;@Column(name="area_id")private Long areaId;@Column(name="area_name",length=200)private String areaName;@Column(name="organization_fingerprint",nullable=false,length=64)private String organizationFingerprint;
 @Column(name="policy_version_id",nullable=false,length=36)private String policyVersionId;@Column(name="policy_fingerprint",nullable=false,length=64)private String policyFingerprint;@Column(name="planning_year",nullable=false)private int planningYear;@Column(nullable=false,length=200)private String title;@Column(nullable=false,length=4000)private String objectives;@Column(name="period_start",nullable=false)private LocalDate periodStart;@Column(name="period_end",nullable=false)private LocalDate periodEnd;@Column(name="estimated_cost",nullable=false,precision=19,scale=2)private BigDecimal estimatedCost;@Column(name="funding_source",nullable=false,length=500)private String fundingSource;
 @Column(name="accountable_employee_id",nullable=false)private Long accountableEmployeeId;@Column(name="accountable_employee_no",nullable=false,length=100)private String accountableEmployeeNo;@Column(name="accountable_name",nullable=false,length=300)private String accountableName;@Column(name="accountable_appointment_id",nullable=false)private Long accountableAppointmentId;@Column(name="accountable_fingerprint",nullable=false,length=64)private String accountableFingerprint;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="content_revision",nullable=false)private int contentRevision;@Column(name="submitted_by",length=100)private String submittedBy;@Column(name="submitted_at")private Instant submittedAt;@Column(name="approved_by",length=100)private String approvedBy;@Column(name="approved_at")private Instant approvedAt;@Column(name="published_by",length=100)private String publishedBy;@Column(name="published_at")private Instant publishedAt;
 protected LdConsolidatedPlan(){}
 public LdConsolidatedPlan(String agency,ScopeType scope,String organizationType,Long organizationId,String organizationCode,String organizationName,Long areaId,String areaName,String organizationFingerprint,String policyVersionId,String policyFingerprint,int year,String title,String objectives,LocalDate start,LocalDate end,BigDecimal cost,String funding,Long employeeId,String employeeNo,String employeeName,Long appointmentId,String employeeFingerprint){super(agency);seriesId=UUID.randomUUID().toString();planVersion=1;scopeType=java.util.Objects.requireNonNull(scope);this.organizationType=requiredText(organizationType,"organizationType").toUpperCase(java.util.Locale.ROOT);if(!java.util.Set.of("AREA","BUSINESS_UNIT").contains(this.organizationType))throw new IllegalArgumentException("Unsupported organizationType");this.organizationId=positive(organizationId,"organizationId");this.organizationCode=requiredText(organizationCode,"organizationCode");this.organizationName=requiredText(organizationName,"organizationName");this.areaId=areaId;this.areaName=optionalText(areaName);this.organizationFingerprint=requiredText(organizationFingerprint,"organizationFingerprint");this.policyVersionId=requiredText(policyVersionId,"policyVersionId");this.policyFingerprint=requiredText(policyFingerprint,"policyFingerprint");if(year<2000||year>2200)throw new IllegalArgumentException("planningYear is invalid");planningYear=year;accountableEmployeeId=positive(employeeId,"accountableEmployeeId");accountableEmployeeNo=requiredText(employeeNo,"accountableEmployeeNo");accountableName=requiredText(employeeName,"accountableName");accountableAppointmentId=positive(appointmentId,"accountableAppointmentId");accountableFingerprint=requiredText(employeeFingerprint,"accountableFingerprint");status=Status.DRAFT;contentRevision=1;apply(title,objectives,start,end,cost,funding);}
 public void update(String title,String objectives,LocalDate start,LocalDate end,BigDecimal cost,String funding){editable();apply(title,objectives,start,end,cost,funding);contentRevision++;}
 public void touch(){editable();contentRevision++;} public void submit(String actor,Instant at){editable();status=Status.SUBMITTED;submittedBy=requiredText(actor,"actor");submittedAt=java.util.Objects.requireNonNull(at);}public void approve(String actor,Instant at){if(status!=Status.SUBMITTED)throw new IllegalStateException("Only a SUBMITTED L&D plan may be approved");status=Status.APPROVED;approvedBy=requiredText(actor,"actor");approvedAt=java.util.Objects.requireNonNull(at);}public void publish(String actor,Instant at){if(status!=Status.APPROVED)throw new IllegalStateException("Only an APPROVED L&D plan may be published");status=Status.PUBLISHED;publishedBy=requiredText(actor,"actor");publishedAt=java.util.Objects.requireNonNull(at);}public void cancel(){if(status!=Status.DRAFT&&status!=Status.SUBMITTED)throw new IllegalStateException("Only a DRAFT or SUBMITTED L&D plan may be cancelled");status=Status.CANCELLED;}
 public LdConsolidatedPlan successor(){if(status!=Status.PUBLISHED)throw new IllegalStateException("Only a PUBLISHED L&D plan may be revised");LdConsolidatedPlan n=new LdConsolidatedPlan(getAgencyId(),scopeType,organizationType,organizationId,organizationCode,organizationName,areaId,areaName,organizationFingerprint,policyVersionId,policyFingerprint,planningYear,title,objectives,periodStart,periodEnd,estimatedCost,fundingSource,accountableEmployeeId,accountableEmployeeNo,accountableName,accountableAppointmentId,accountableFingerprint);n.seriesId=seriesId;n.planVersion=planVersion+1;n.supersedesId=getId();return n;}
 private void apply(String t,String o,LocalDate s,LocalDate e,BigDecimal c,String f){title=requiredText(t,"title");objectives=requiredText(o,"objectives");if(s==null||e==null||e.isBefore(s))throw new IllegalArgumentException("Valid plan period is required");periodStart=s;periodEnd=e;if(c==null||c.signum()<0)throw new IllegalArgumentException("estimatedCost cannot be negative");estimatedCost=c.setScale(2,java.math.RoundingMode.HALF_UP);fundingSource=requiredText(f,"fundingSource");}private void editable(){if(status!=Status.DRAFT)throw new IllegalStateException("Only a DRAFT L&D plan may be changed");}private static Long positive(Long v,String n){if(v==null||v<1)throw new IllegalArgumentException(n+" is required");return v;}
 public String getSeriesId(){return seriesId;}public int getPlanVersion(){return planVersion;}public String getSupersedesId(){return supersedesId;}public ScopeType getScopeType(){return scopeType;}public String getOrganizationType(){return organizationType;}public Long getOrganizationId(){return organizationId;}public String getOrganizationCode(){return organizationCode;}public String getOrganizationName(){return organizationName;}public Long getAreaId(){return areaId;}public String getAreaName(){return areaName;}public String getOrganizationFingerprint(){return organizationFingerprint;}public String getPolicyVersionId(){return policyVersionId;}public String getPolicyFingerprint(){return policyFingerprint;}public int getPlanningYear(){return planningYear;}public String getTitle(){return title;}public String getObjectives(){return objectives;}public LocalDate getPeriodStart(){return periodStart;}public LocalDate getPeriodEnd(){return periodEnd;}public BigDecimal getEstimatedCost(){return estimatedCost;}public String getFundingSource(){return fundingSource;}public Long getAccountableEmployeeId(){return accountableEmployeeId;}public String getAccountableEmployeeNo(){return accountableEmployeeNo;}public String getAccountableName(){return accountableName;}public Long getAccountableAppointmentId(){return accountableAppointmentId;}public String getAccountableFingerprint(){return accountableFingerprint;}public Status getStatus(){return status;}public int getContentRevision(){return contentRevision;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}public String getApprovedBy(){return approvedBy;}public Instant getApprovedAt(){return approvedAt;}public String getPublishedBy(){return publishedBy;}public Instant getPublishedAt(){return publishedAt;}
}
